changeSet.sql:

if not exists (select 1 from [sys].[key_constraints] where name = 'PK_MetricAssetVersionConditionItemValue')
begin
	ALTER TABLE [metrics].[AssetVersionConditionItemValue] ADD CONSTRAINT [PK_MetricAssetVersionConditionItemValue] PRIMARY KEY CLUSTERED ( [Uid] ASC, [Value] ASC )
end

if not exists (select 1 from [INFORMATION_SCHEMA].[REFERENTIAL_CONSTRAINTS] where constraint_name = 'FK_MetricAssetVersionConditionItemValue_MetricAssetVersionConditionItem')
begin
	ALTER TABLE [metrics].[AssetVersionConditionItemValue] WITH CHECK ADD CONSTRAINT [FK_MetricAssetVersionConditionItemValue_MetricAssetVersionConditionItem] FOREIGN KEY([Uid]) REFERENCES [metrics].[AssetVersionConditionItem] ([Uid]) ON DELETE CASCADE;
	ALTER TABLE [metrics].[AssetVersionConditionItemValue] CHECK CONSTRAINT [FK_MetricAssetVersionConditionItemValue_MetricAssetVersionConditionItem];
end
